def verify_password_reset_token(*, session, token):
    payload = security.decode_token(token, security.TOKEN_TYPE_PASSWORD_RESET)
    user = session.get(User, uuid.UUID(payload["sub"]))
    if not user or not hmac.compare_digest(payload.get("pwd", ""), security.password_fingerprint(user.hashed_password)):
        return None
    return user

